require "logger"
require "monitor"

module EventBus
  class EventBusError < StandardError; end
  class InvalidTopicError < EventBusError; end
  class InvalidSubscriberError < EventBusError; end
  class SubscriberNotFoundError < EventBusError; end

  Event = Struct.new(:topic, :payload, :timestamp, keyword_init: true)

  class Bus
    def initialize(logger: nil)
      @logger = logger || Logger.new($stdout, level: Logger::INFO)
      @subscribers = {}
      @monitor = Monitor.new
    end

    def subscribe(topic, subscriber_id = nil, &callback)
      validate_topic!(topic)

      if callback.nil? && !subscriber_id.respond_to?(:call)
        raise InvalidSubscriberError, "subscriber must be a callable or a block"
      end

      callable = block_given? ? callback : subscriber_id
      id = subscriber_id.is_a?(String) ? subscriber_id : generate_id(topic)

      validate_callable!(callable)

      @monitor.synchronize do
        @subscribers[topic] ||= {}
        if @subscribers[topic].key?(id)
          raise InvalidSubscriberError, "subscriber '#{id}' already subscribed to '#{topic}'"
        end

        @subscribers[topic][id] = callable
        @logger.info("Subscribed: id=#{id} topic=#{topic}")
      end

      id
    end

    def unsubscribe(topic, subscriber_id)
      validate_topic!(topic)
      validate_subscriber_id!(subscriber_id)

      @monitor.synchronize do
        unless @subscribers.dig(topic, subscriber_id)
          raise SubscriberNotFoundError, "subscriber '#{subscriber_id}' not found for topic '#{topic}'"
        end

        @subscribers[topic].delete(subscriber_id)
        @subscribers.delete(topic) if @subscribers[topic].empty?
        @logger.info("Unsubscribed: id=#{subscriber_id} topic=#{topic}")
      end
    end

    def publish(topic, payload = nil)
      validate_topic!(topic)

      event = Event.new(
        topic: topic,
        payload: payload,
        timestamp: monotonic_now
      )

      subscribers = @monitor.synchronize do
        @subscribers[topic]&.dup || {}
      end

      if subscribers.empty?
        @logger.debug("No subscribers for topic '#{topic}'")
        return []
      end

      results = []
      subscribers.each do |id, callable|
        begin
          callable.call(event)
          results << { subscriber_id: id, status: :ok }
          @logger.debug("Dispatched event to subscriber=#{id} topic=#{topic}")
        rescue => e
          results << { subscriber_id: id, status: :error, error: e }
          @logger.error("Subscriber #{id} raised #{e.class}: #{e.message}")
        end
      end

      @logger.info("Published event: topic=#{topic} subscribers=#{subscribers.size}")
      results
    end

    def subscriber_count(topic = nil)
      @monitor.synchronize do
        if topic
          @subscribers[topic]&.size || 0
        else
          @subscribers.sum { |_, subs| subs.size }
        end
      end
    end

    def topics
      @monitor.synchronize { @subscribers.keys }
    end

    def subscribed?(topic, subscriber_id)
      validate_topic!(topic)
      validate_subscriber_id!(subscriber_id)
      @monitor.synchronize { @subscribers.dig(topic, subscriber_id) != nil }
    end

    def clear
      @monitor.synchronize do
        count = subscriber_count
        @subscribers.clear
        @logger.info("Cleared all subscribers (#{count} removed)")
      end
    end

    private

    def validate_topic!(topic)
      unless topic.is_a?(String) && !topic.empty?
        raise InvalidTopicError, "topic must be a non-empty String"
      end
    end

    def validate_subscriber_id!(id)
      unless id.is_a?(String) && !id.empty?
        raise ArgumentError, "subscriber_id must be a non-empty String"
      end
    end

    def validate_callable!(callable)
      unless callable.respond_to?(:call)
        raise InvalidSubscriberError, "subscriber must respond to #call"
      end
    end

    def generate_id(topic)
      "#{topic}-#{SecureRandom.hex(4)}"
    end

    def monotonic_now
      Process.clock_gettime(Process::CLOCK_MONOTONIC)
    end
  end
end

require "minitest/autorun"
require "logger"
require "stringio"
require_relative "event_bus"

class EventBusTest < Minitest::Test
  include EventBus

  def setup
    @log_output = StringIO.new
    @logger = Logger.new(@log_output, level: Logger::DEBUG)
    @bus = Bus.new(logger: @logger)
  end

  # --- publish and subscribe ---

  def test_subscribe_and_publish_with_block
    received = nil
    @bus.subscribe("click") { |e| received = e }
    @bus.publish("click", { x: 10, y: 20 })

    assert_kind_of Event, received
    assert_equal "click", received.topic
    assert_equal({ x: 10, y: 20 }, received.payload)
    assert_kind_of Numeric, received.timestamp
  end

  def test_subscribe_with_named_id
    received = nil
    @bus.subscribe("click", "handler-1") { |e| received = e }
    @bus.publish("click")

    assert_equal "handler-1", @bus.subscribed?("click", "handler-1") ? "handler-1" : nil
    assert_kind_of Event, received
  end

  def test_subscribe_with_callable
    received = nil
    handler = ->(e) { received = e }
    @bus.subscribe("submit", handler)
    @bus.publish("submit", "form-data")

    assert_equal "form-data", received.payload
  end

  def test_subscribe_with_named_callable
    received = nil
    handler = ->(e) { received = e }
    @bus.subscribe("submit", "my-handler", handler)
    @bus.publish("submit")

    assert_kind_of Event, received
    assert @bus.subscribed?("submit", "my-handler")
  end

  def test_publish_returns_results
    @bus.subscribe("ev") { |e| }
    @bus.subscribe("ev") { |e| }
    results = @bus.publish("ev")

    assert_equal 2, results.size
    assert results.all? { |r| r[:status] == :ok }
  end

  def test_publish_returns_empty_for_no_subscribers
    results = @bus.publish("unknown")
    assert_empty results
  end

  # --- multiple subscribers per topic ---

  def test_multiple_subscribers_receive_event
    received = []
    3.times { |i| @bus.subscribe("ev") { |e| received << i } }
    @bus.publish("ev")

    assert_equal [0, 1, 2], received.sort
  end

  def test_different_topics_independent
    a_received = false
    b_received = false
    @bus.subscribe("a") { a_received = true }
    @bus.subscribe("b") { b_received = true }

    @bus.publish("a")
    assert a_received
    refute b_received
  end

  # --- unsubscribe ---

  def test_unsubscribe
    received = false
    id = @bus.subscribe("ev") { received = true }
    @bus.unsubscribe("ev", id)
    @bus.publish("ev")

    refute received
    refute @bus.subscribed?("ev", id)
  end

  def test_unsubscribe_named
    @bus.subscribe("ev", "h1") {}
    @bus.unsubscribe("ev", "h1")
    refute @bus.subscribed?("ev", "h1")
  end

  def test_unsubscribe_nonexistent_raises
    assert_raises(SubscriberNotFoundError) { @bus.unsubscribe("ev", "nope") }
  end

  def test_unsubscribe_wrong_topic_raises
    @bus.subscribe("ev", "h1") {}
    assert_raises(SubscriberNotFoundError) { @bus.unsubscribe("other", "h1") }
  end

  def test_unsubscribe_error_message_includes_id
    err = assert_raises(SubscriberNotFoundError) { @bus.unsubscribe("ev", "nope") }
    assert_match(/nope/, err.message)
  end

  # --- duplicate subscriber ---

  def test_duplicate_named_subscriber_raises
    @bus.subscribe("ev", "h1") {}
    assert_raises(InvalidSubscriberError) { @bus.subscribe("ev", "h1") {} }
  end

  def test_duplicate_error_message
    @bus.subscribe("ev", "h1") {}
    err = assert_raises(InvalidSubscriberError) { @bus.subscribe("ev", "h1") {} }
    assert_match(/h1/, err.message)
  end

  # --- subscriber_count ---

  def test_subscriber_count_per_topic
    2.times { |i| @bus.subscribe("a", "a-#{i}") {} }
    3.times { |i| @bus.subscribe("b", "b-#{i}") {} }

    assert_equal 2, @bus.subscriber_count("a")
    assert_equal 3, @bus.subscriber_count("b")
  end

  def test_subscriber_count_total
    2.times { |i| @bus.subscribe("a", "a-#{i}") {} }
    3.times { |i| @bus.subscribe("b", "b-#{i}") {} }

    assert_equal 5, @bus.subscriber_count
  end

  def test_subscriber_count_unknown_topic
    assert_equal 0, @bus.subscriber_count("nope")
  end

  def test_subscriber_count_after_unsubscribe
    @bus.subscribe("ev", "h1") {}
    @bus.subscribe("ev", "h2") {}
    @bus.unsubscribe("ev", "h1")

    assert_equal 1, @bus.subscriber_count("ev")
    assert_equal 1, @bus.subscriber_count
  end

  # --- topics ---

  def test_topics
    @bus.subscribe("a") {}
    @bus.subscribe("b") {}
    @bus.subscribe("c") {}

    assert_equal %w[a b c], @bus.topics.sort
  end

  def test_topics_empty
    assert_empty @bus.topics
  end

  def test_topics_after_unsubscribe_all
    id = @bus.subscribe("a") {}
    @bus.unsubscribe("a", id)

    assert_empty @bus.topics
  end

  # --- clear ---

  def test_clear_removes_all
    @bus.subscribe("a", "h1") {}
    @bus.subscribe("b", "h2") {}
    @bus.clear

    assert_equal 0, @bus.subscriber_count
    assert_empty @bus.topics
  end

  # --- error handling ---

  def test_subscriber_error_does_not_affect_others
    results = []
    @bus.subscribe("ev", "bad") { raise "boom" }
    @bus.subscribe("ev", "good") { |e| results << :ok }

    publish_results = @bus.publish("ev")

    assert_equal [:ok], results
    assert_equal 2, publish_results.size

    bad = publish_results.find { |r| r[:subscriber_id] == "bad" }
    good = publish_results.find { |r| r[:subscriber_id] == "good" }

    assert_equal :error, bad[:status]
    assert_instance_of RuntimeError, bad[:error]
    assert_equal :ok, good[:status]
  end

  def test_subscriber_error_logged
    @bus.subscribe("ev") { raise "boom" }
    @bus.publish("ev")

    assert_match(/RuntimeError/, @log_output.string)
    assert_match(/boom/, @log_output.string)
  end

  # --- argument validation ---

  def test_nil_topic_raises
    assert_raises(InvalidTopicError) { @bus.subscribe(nil) {} }
  end

  def test_empty_topic_raises
    assert_raises(InvalidTopicError) { @bus.subscribe("") {} }
  end

  def test_non_string_topic_raises
    assert_raises(InvalidTopicError) { @bus.subscribe(123) {} }
  end

  def test_publish_nil_topic_raises
    assert_raises(InvalidTopicError) { @bus.publish(nil) }
  end

  def test_no_callable_raises
    assert_raises(InvalidSubscriberError) { @bus.subscribe("ev") }
  end

  def test_unsubscribe_nil_id_raises
    assert_raises(ArgumentError) { @bus.unsubscribe("ev", nil) }
  end

  def test_unsubscribe_empty_id_raises
    assert_raises(ArgumentError) { @bus.unsubscribe("ev", "") }
  end

  def test_subscribed_nil_topic_raises
    assert_raises(InvalidTopicError) { @bus.subscribed?(nil, "h1") }
  end

  def test_subscribed_nil_id_raises
    assert_raises(ArgumentError) { @bus.subscribed?("ev", nil) }
  end

  # --- auto-generated IDs are unique ---

  def test_auto_ids_are_unique
    ids = 100.times.map { @bus.subscribe("ev") {} }
    assert_equal ids.uniq.size, ids.size
  end

  # --- logging ---

  def test_logging_on_subscribe
    @bus.subscribe("ev", "h1") {}
    assert_match(/Subscribed.*id=h1.*topic=ev/, @log_output.string)
  end

  def test_logging_on_unsubscribe
    @bus.subscribe("ev", "h1") {}
    @log_output.truncate(0)
    @bus.unsubscribe("ev", "h1")
    assert_match(/Unsubscribed.*id=h1.*topic=ev/, @log_output.string)
  end

  def test_logging_on_publish
    @bus.subscribe("ev") {}
    @log_output.truncate(0)
    @bus.publish("ev")
    assert_match(/Published event.*topic=ev/, @log_output.string)
  end

  def test_logging_no_subscribers
    @bus.publish("ev")
    assert_match(/No subscribers for topic/, @log_output.string)
  end

  # --- concurrent access ---

  def test_concurrent_subscribe_and_publish
    bus = Bus.new(logger: @logger)
    n = 50
    received = []
    mutex = Mutex.new
    errors = []

    threads = n.times.map do |i|
      Thread.new do
        begin
          bus.subscribe("ev", "h-#{i}") { |e| mutex.synchronize { received << i } }
        rescue => e
          mutex.synchronize { errors << e }
        end
      end
    end
    threads.each(&:join)

    assert_empty errors
    assert_equal n, bus.subscriber_count("ev")

    bus.publish("ev")
    assert_equal n, received.size
  end

  def test_concurrent_unsubscribe
    bus = Bus.new(logger: @logger)
    50.times { |i| bus.subscribe("ev", "h-#{i}") {} }

    threads = 50.times.map do |i|
      Thread.new { bus.unsubscribe("ev", "h-#{i}") }
    end
    threads.each(&:join)

    assert_equal 0, bus.subscriber_count
  end

  def test_concurrent_publish_is_thread_safe
    bus = Bus.new(logger: @logger)
    counts = []
    mutex = Mutex.new

    bus.subscribe("ev") { |e| mutex.synchronize { counts << 1 } }

    threads = 10.times.map do
      Thread.new { bus.publish("ev") }
    end
    threads.each(&:join)

    assert_equal 10, counts.size
  end
end
